      state.vel.x = 0; state.vel.z = 0; state.vel.y = Math.min(state.vel.y, 0);
    }
    if (state.pos.y <= TASK.bodyHeight) {
      if (state.airborne && (norm(state.vel) > TASK.contactCrashSpeed || Math.max(Math.abs(att.roll), Math.abs(att.pitch)) > TASK.landingTilt * 2)) state.reason = "floor crash";
      state.pos.y = TASK.bodyHeight; state.vel.y = Math.max(0, state.vel.y);
      state.vel.x *= Math.exp(-12 * dt); state.vel.z *= Math.exp(-12 * dt);
    }
    for (let i = 0; i < GATES.length; i++) {
      const gate = GATES[i], x = gate.centre.x;
      if ((old.x < x && state.pos.x >= x) || (old.x > x && state.pos.x <= x)) {
        const fraction = (x - old.x) / (state.pos.x - old.x);
        const y = old.y + fraction * (state.pos.y - old.y), z = old.z + fraction * (state.pos.z - old.z);
        const dy = Math.abs(y - gate.centre.y), dz = Math.abs(z - gate.centre.z);
        const half = TASK.gateOpening / 2, outer = half + TASK.gateFrame;
        const fits = dy + TASK.bodyHeight <= half && dz + TASK.bodyRadius <= half;
        const overlapsFrame = dy <= outer + TASK.bodyHeight && dz <= outer + TASK.bodyRadius && !fits;
        if (overlapsFrame) state.reason = `gate ${i} frame collision (dy=${dy.toFixed(3)}, dz=${dz.toFixed(3)})`;
        if (i === state.gateIndex && old.x < x && state.pos.x >= x && fits) state.gateIndex++;
      }
    }
    const error = Math.hypot(state.pos.x - PAD.centre.x, state.pos.z - PAD.centre.z);
    if (state.gateIndex === GATES.length && error <= TASK.landingRadius && state.pos.y <= TASK.bodyHeight + 0.025 &&
        norm(state.vel) < TASK.landingSpeed && Math.max(Math.abs(att.roll), Math.abs(att.pitch)) < TASK.landingTilt) state.landedFor += dt;
    else state.landedFor = 0;
    if (state.landedFor >= TASK.landingHold && !state.reason) state.reason = "landed";
  }

  let pass = 0;
  for (let seed = 1; seed <= 500; seed++) {
    const params = trialParameters(seed), state = initialState(params);
    const pStart = copy(state.pos);
    const waypoints = [
      { p: pStart, v: { x: 0, y: 0, z: 0 }, a: { x: 0, y: 0, z: 0 } },
      { p: GATES[0].centre, v: { x: 0.95, y: 0, z: 0 }, a: { x: 0, y: 0, z: 0 } },
      { p: GATES[1].centre, v: { x: 1.0, y: 0, z: 0 }, a: { x: 0, y: 0, z: 0 } },
      { p: GATES[2].centre, v: { x: 0.90, y: 0, z: 0 }, a: { x: 0, y: 0, z: 0 } },
      { p: { x: PAD.centre.x, y: 0.13, z: PAD.centre.z }, v: { x: 0, y: -0.10, z: 0 }, a: { x: 0, y: 0, z: 0 } },
      { p: { x: PAD.centre.x, y: 0.07, z: PAD.centre.z }, v: { x: 0, y: 0, z: 0 }, a: { x: 0, y: 0, z: 0 } },
    ];
    const times = [0, 1.85, 3.55, 5.15, 6.65, 7.15];
    const getRef = (t) => {
      if (t >= times[times.length - 1]) return { pos: { x: PAD.centre.x, y: 0.07, z: PAD.centre.z }, vel: { x: 0, y: 0, z: 0 }, acc: { x: 0, y: 0, z: 0 } };
      let seg = 0;
      while (seg < times.length - 2 && t >= times[seg + 1]) seg++;
      const t0 = times[seg], t1 = times[seg + 1];
      return sampleQuintic(waypoints[seg].p, waypoints[seg].v, waypoints[seg].a, waypoints[seg + 1].p, waypoints[seg + 1].v, waypoints[seg + 1].a, t1 - t0, t - t0);
    };

    for (let step = 0; step < 2500 && !state.reason; step++) {
      const s = state, t = s.t;
      const ref = getRef(t);
      const refLead = getRef(t + 0.14 + 0.8 * params.lag);
      const wPrev = getPreviewWind(params, t);
      const windCurr = getWindAt(params, t);
      const wEff = { x: 0.2 * windCurr.x + 0.8 * wPrev.x, y: 0, z: 0.2 * windCurr.z + 0.8 * wPrev.z };

      const kpX = 6.5, kdX = 4.5;
      const kpZ = 8.0, kdZ = 5.0;
      const kpY = 10.0, kdY = 5.5;

      const ax = refLead.acc.x + kpX * (ref.pos.x - s.pos.x) + kdX * (ref.vel.x - s.vel.x);
      let ay = refLead.acc.y + kpY * (ref.pos.y - s.pos.y) + kdY * (ref.vel.y - s.vel.y);
      const az = refLead.acc.z + kpZ * (ref.pos.z - s.pos.z) + kdZ * (ref.vel.z - s.vel.z);

      const landingPhase = t >= 6.85 && s.gateIndex === 3;
      if (landingPhase && s.pos.y <= 0.085 && Math.hypot(s.pos.x - PAD.centre.x, s.pos.z - PAD.centre.z) < 0.12) {
        ay = Math.min(ay, -2.0);
      }

      const Fx = params.mass * ax + TASK.linearDrag * (s.vel.x - wEff.x);
      const Fy = Math.max(0.5, params.mass * (TASK.gravity + ay) + TASK.linearDrag * s.vel.y);
      const Fz = params.mass * az + TASK.linearDrag * (s.vel.z - wEff.z);

      const cy = Math.cos(s.att.yaw), sy = Math.sin(s.att.yaw);
      const Fbx = cy * Fx - sy * Fz;
      const Fbz = sy * Fx + cy * Fz;
      const Ftot = Math.hypot(Fbx, Fy, Fbz);

      const maxTilt = landingPhase && s.pos.y <= 0.11 ? 0.155 : 0.52;
      const rollDes = clamp(-Math.asin(clamp(Fbz / Ftot, -0.9, 0.9)), -maxTilt, maxTilt);
      const pitchDes = clamp(Math.atan2(Fbx, Fy), -maxTilt, maxTilt);

      const inertia = TASK.inertia * params.mass / TASK.baseMass;
      const kpAtt = 80, kdAtt = 15.5;
      const tauRoll = inertia * (kpAtt * (rollDes - s.att.roll) - kdAtt * s.rates.roll);
      const tauPitch = inertia * (kpAtt * (pitchDes - s.att.pitch) - kdAtt * s.rates.pitch);
      const tauYaw = inertia * (-40 * s.att.yaw - 10 * s.rates.yaw);

      const cosTilt = Math.max(0.5, Math.cos(s.att.roll) * Math.cos(s.att.pitch));
      let Fcmd = Fy / cosTilt;
      if (landingPhase && s.pos.y <= 0.075 && Math.hypot(s.pos.x - PAD.centre.x, s.pos.z - PAD.centre.z) < 0.12 && norm(s.vel) < 0.35) {
        Fcmd = 0.25 * params.mass * TASK.gravity;
      }

      const desired = [0, 0, 0, 0];
      for (let i = 0; i < 4; i++) {
        const tMot = Fcmd / 4 +
          tauRoll * MOTOR_Z[i] / (4 * TASK.arm) -
          tauPitch * MOTOR_X[i] / (4 * TASK.arm) +
          tauYaw * SPIN[i] / (4 * TASK.yawCoefficient);
        const scale = i === params.weakMotor ? 1 - params.weakness : 1;
        desired[i] = clamp(tMot / scale, 0, TASK.maxMotorThrust);
      }

      const thrustCmd = (desired[0] + desired[1] + desired[2] + desired[3]) / (4 * TASK.maxMotorThrust);
      const mixRoll = TASK.arm * (desired[0] * MOTOR_Z[0] + desired[1] * MOTOR_Z[1] + desired[2] * MOTOR_Z[2] + desired[3] * MOTOR_Z[3]);
      const mixPitch = -TASK.arm * (desired[0] * MOTOR_X[0] + desired[1] * MOTOR_X[1] + desired[2] * MOTOR_X[2] + desired[3] * MOTOR_X[3]);
      const mixYaw = TASK.yawCoefficient * (desired[0] * SPIN[0] + desired[1] * SPIN[1] + desired[2] * SPIN[2] + desired[3] * SPIN[3]);

      const dtSub = 0.005;
      const solveAxis = (axis, tauMix) => {
        const u = tauMix / inertia;
        const rate = s.rates[axis];
        const intPrev = s.integral[axis];
        let err = (u + 13 * rate - 22 * intPrev) / (65 + 22 * dtSub);
        const intNew = intPrev + err * dtSub;
        if (intNew > 0.35 || intNew < -0.35) {
          const intClamped = clamp(intNew, -0.35, 0.35);
          err = (u + 13 * rate - 22 * intClamped) / 65;
        }
        return clamp(s.att[axis] + err, -0.6, 0.6);
      };

      const action = {
        thrust: clamp(thrustCmd, 0, 1),
        roll: solveAxis("roll", mixRoll),
        pitch: solveAxis("pitch", mixPitch),
        yawRate: clamp(s.rates.yaw + mixYaw / (8 * inertia), -2, 2),
      };

      for (let sub = 0; sub < 2 && !state.reason; sub++) integrate(state, action, params, 0.005);
    }
    if (state.reason === "landed") pass++;
    else console.log(`seed ${seed}: ${state.reason || "time limit"} at t=${state.t.toFixed(2)}, gates=${state.gateIndex}`);
  }
  console.log(`Passed ${pass}/500`);
});
'

