      const action = {
        thrust: clamp(thrustCmd, 0, 1),
        roll: solveAxis('roll', mixRoll),
        pitch: solveAxis('pitch', mixPitch),
        yawRate: clamp(s.rates.yaw + mixYaw / (8 * inertia), -2, 2),
      };

      for (let sub = 0; sub < TASK.substeps; sub++) {
        stepSim(shadow, action, params, dtSub);
      }

      return action;
    },
  };
}

